select *, corr(credit_limit, age) over (partition by segment) as corr_credit_limit_age, corr(credit_limit, age) over (partition by city) as corr_credit_limit_age_2, percent_rank() over (partition by segment order by age desc) as age_percent_rank, lag(credit_limit, 1) over (partition by country order by credit_limit asc, id asc) as prev_credit_limit, avg(credit_limit) over (partition by segment order by credit_limit asc, id asc rows between 6 preceding and current row) as credit_limit_avg_6 from customers
